-- Edit maintained student_transfers sources; retain all earlier migrations.
BEGIN;

-- SOURCE direct/tables.sql sha256=a9f9887caef1786f684872116e4821800bfabeae23883199e221e9df510ed51b
-- Direct transfers are made by an administrator or a Head of Department and
-- apply immediately. They reuse the request row as placement history.
ALTER TABLE public.student_transfer_requests
    ADD COLUMN initiated_by text NOT NULL DEFAULT 'student'
        CHECK (initiated_by IN ('student', 'admin', 'hod'));

ALTER TABLE public.student_transfer_events
    DROP CONSTRAINT student_transfer_events_action_check,
    ADD CONSTRAINT student_transfer_events_action_check CHECK (action IN (
        'submitted', 'review_started', 'approved', 'rejected', 'cancelled', 'transferred'));

-- SOURCE direct/apply.sql sha256=b49333cf9b10acc26cf11e369131883d5b07ceb8ef74ec9e25fbeabcc430c928
-- One placement move shared by request approval and direct transfers. The
-- caller holds the tenant academic lock and has authorized p_role.
CREATE FUNCTION public.transfer_apply(
    p_actor uuid, p_tenant uuid, p_request uuid, p_role text, p_comment text
) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_request public.student_transfer_requests; v_registration public.student_semester_registrations;
    v_enrollments jsonb;
BEGIN
    SELECT * INTO v_request FROM public.student_transfer_requests
    WHERE transfer_request_id = p_request AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer request not found' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_registration FROM public.student_semester_registrations
    WHERE semester_registration_id = v_request.semester_registration_id AND institution_id = p_tenant
    FOR UPDATE;
    IF NOT FOUND OR v_registration.student_id <> v_request.student_id
       OR v_registration.academic_section_id <> v_request.from_section_id
       OR v_registration.semester_registration_id IS DISTINCT FROM
          public.transfer_current_registration(v_request.student_id, p_tenant) THEN
        RAISE EXCEPTION 'The student''s section changed after this request was submitted'
            USING ERRCODE = 'P1102';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.semesters WHERE semester_id = v_registration.semester_id
                   AND is_active AND end_date >= current_date) THEN
        RAISE EXCEPTION 'The current term is closed' USING ERRCODE = 'P1103';
    END IF;
    IF public.transfer_target_type(v_request.from_section_id, v_request.to_section_id, p_tenant)
       IS DISTINCT FROM v_request.transfer_type THEN
        RAISE EXCEPTION 'The requested section is unavailable' USING ERRCODE = 'P1104';
    END IF;
    IF NOT public.transfer_section_has_seat(v_request.to_section_id) THEN
        RAISE EXCEPTION 'The requested section is full' USING ERRCODE = 'P1105';
    END IF;
    SELECT COALESCE(jsonb_agg(soe.subject_snapshot || jsonb_build_object(
            'academic_offering_id', soe.academic_offering_id, 'enrolled_at', soe.enrolled_at)
        ORDER BY soe.enrolled_at, soe.offering_enrollment_id), '[]'::jsonb)
    INTO v_enrollments
    FROM public.student_offering_enrollments soe
    WHERE soe.semester_registration_id = v_registration.semester_registration_id;
    -- Offerings belong to the old section, so they cannot follow the student.
    DELETE FROM public.student_offering_enrollments
    WHERE semester_registration_id = v_registration.semester_registration_id;
    UPDATE public.student_semester_registrations
    SET academic_section_id = v_request.to_section_id, status = 'assigned',
        selected_option_ids = '{}'::uuid[], registered_at = NULL, assigned_at = now()
    WHERE semester_registration_id = v_registration.semester_registration_id;
    UPDATE public.student_transfer_requests
    SET status = 'approved', decided_by = p_actor, decided_at = now(), decided_as = p_role,
        decision_comment = p_comment, previous_registration = to_jsonb(v_registration),
        previous_enrollments = v_enrollments, updated_at = now()
    WHERE transfer_request_id = p_request;
END;
$$;

-- Same contract as before; approval now delegates the move to transfer_apply.
CREATE OR REPLACE FUNCTION public.decide_student_transfer(
    p_actor uuid, p_tenant uuid, p_request uuid, p_action text, p_comment text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_request public.student_transfer_requests; v_role text; v_status text;
    v_comment text := NULLIF(btrim(COALESCE(p_comment, '')), '');
BEGIN
    PERFORM public.assert_transfer_backend();
    IF p_action IS NULL OR p_action NOT IN ('start_review', 'approve', 'reject') THEN
        RAISE EXCEPTION 'Unknown transfer action' USING ERRCODE = '22023';
    END IF;
    IF length(v_comment) > 2000 THEN
        RAISE EXCEPTION 'Comments are limited to 2000 characters' USING ERRCODE = '22023';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:' || p_tenant::text, 0));
    SELECT * INTO v_request FROM public.student_transfer_requests
    WHERE transfer_request_id = p_request AND institution_id = p_tenant FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transfer request not found' USING ERRCODE = 'P0002';
    END IF;
    IF public.transfer_admin_allowed(p_actor, p_tenant, 'transfers.approve') THEN
        v_role := 'admin';
    ELSIF v_request.to_department_id = ANY (public.transfer_hod_departments(p_actor, p_tenant)) THEN
        v_role := 'hod';
    ELSE
        RAISE EXCEPTION 'Only an administrator or the receiving department HOD can decide this request'
            USING ERRCODE = '42501';
    END IF;
    IF v_request.status NOT IN ('submitted', 'under_review') THEN
        RAISE EXCEPTION 'This transfer request is already closed' USING ERRCODE = 'P1101';
    END IF;
    IF p_action = 'start_review' THEN
        IF v_request.status = 'submitted' THEN
            UPDATE public.student_transfer_requests
            SET status = 'under_review', review_started_by = p_actor,
                review_started_at = now(), updated_at = now()
            WHERE transfer_request_id = p_request;
            INSERT INTO public.student_transfer_events
                (institution_id, transfer_request_id, actor_user_id, action, comment)
            VALUES (p_tenant, p_request, p_actor, 'review_started', v_comment);
        END IF;
        v_status := 'under_review';
    ELSIF p_action = 'reject' THEN
        IF v_comment IS NULL THEN
            RAISE EXCEPTION 'A rejection reason is required' USING ERRCODE = 'P1109';
        END IF;
        UPDATE public.student_transfer_requests
        SET status = 'rejected', decided_by = p_actor, decided_at = now(), decided_as = v_role,
            decision_comment = v_comment, updated_at = now()
        WHERE transfer_request_id = p_request;
        INSERT INTO public.student_transfer_events
            (institution_id, transfer_request_id, actor_user_id, action, comment)
        VALUES (p_tenant, p_request, p_actor, 'rejected', v_comment);
        v_status := 'rejected';
    ELSE
        PERFORM public.transfer_apply(p_actor, p_tenant, p_request, v_role, v_comment);
        INSERT INTO public.student_transfer_events
            (institution_id, transfer_request_id, actor_user_id, action, comment)
        VALUES (p_tenant, p_request, p_actor, 'approved', v_comment);
        v_status := 'approved';
    END IF;
    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.transfer.' || p_action, 'student_transfer_requests',
        p_request::text, jsonb_build_object('decided_as', v_role, 'before_status', v_request.status,
            'after_status', v_status, 'comment', v_comment));
    RETURN jsonb_build_object('transfer_request_id', p_request, 'institution_id', p_tenant,
        'status', v_status);
END;
$$;

-- SOURCE direct/reads.sql sha256=3c22f2ccbc7f68e8b2b1f657b65beacdbcf57c815da8bd353abc84aa18a3a9e5
-- Request history now states who started each transfer.
CREATE OR REPLACE FUNCTION public.transfer_requests_json(
    p_tenant uuid, p_student uuid, p_departments uuid[], p_open_only boolean
) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'transfer_request_id', t.transfer_request_id, 'student_id', t.student_id,
        'student_name', COALESCE(NULLIF(btrim(u.display_name), ''),
            NULLIF(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email),
        'register_number', COALESCE(s.register_number, s.student_number),
        'transfer_type', t.transfer_type, 'status', t.status, 'reason', t.reason,
        'initiated_by', t.initiated_by,
        'from_section', public.transfer_section_json(t.from_section_id, p_tenant),
        'to_section', public.transfer_section_json(t.to_section_id, p_tenant),
        'submitted_at', t.submitted_at, 'review_started_at', t.review_started_at,
        'decided_at', t.decided_at, 'decided_as', t.decided_as,
        'decision_comment', t.decision_comment, 'cancelled_at', t.cancelled_at,
        'previous_enrollments', t.previous_enrollments,
        'events', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'action', e.action, 'comment', e.comment, 'created_at', e.created_at
            ) ORDER BY e.created_at, e.transfer_event_id), '[]'::jsonb)
            FROM public.student_transfer_events e
            WHERE e.transfer_request_id = t.transfer_request_id
        )
    ) ORDER BY t.submitted_at DESC, t.transfer_request_id), '[]'::jsonb)
    FROM public.student_transfer_requests t
    JOIN public.students s ON s.student_id = t.student_id
    LEFT JOIN public.users u ON u.id = s.user_id
    WHERE t.institution_id = p_tenant
      AND (p_student IS NULL OR t.student_id = p_student)
      AND (p_departments IS NULL OR t.to_department_id = ANY (p_departments))
      AND (NOT p_open_only OR t.status IN ('submitted', 'under_review'));
$$;

-- 'admin' with transfers.approve, 'hod' for a current Head of Department, else NULL.
CREATE FUNCTION public.transfer_direct_role(p_actor uuid, p_tenant uuid)
RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
    SELECT CASE
        WHEN public.transfer_admin_allowed(p_actor, p_tenant, 'transfers.approve') THEN 'admin'
        WHEN cardinality(public.transfer_hod_departments(p_actor, p_tenant)) > 0 THEN 'hod'
    END;
$$;

-- Approved active students with a section in an open term. An HOD only sees
-- students whose current program belongs to a department they head.
CREATE FUNCTION public.read_direct_transfer_students(p_actor uuid, p_tenant uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_role text; v_departments uuid[];
BEGIN
    PERFORM public.assert_transfer_backend();
    v_role := public.transfer_direct_role(p_actor, p_tenant);
    IF v_role IS NULL THEN
        RETURN jsonb_build_object('institution_id', p_tenant, 'can_transfer', false,
            'actor_role', NULL, 'students', '[]'::jsonb);
    END IF;
    IF v_role = 'hod' THEN
        v_departments := public.transfer_hod_departments(p_actor, p_tenant);
    END IF;
    RETURN jsonb_build_object(
        'institution_id', p_tenant, 'can_transfer', true, 'actor_role', v_role,
        'students', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'student_id', candidate.student_id, 'student_name', candidate.student_name,
                'register_number', candidate.register_number,
                'current_section', public.transfer_section_json(reg.academic_section_id, p_tenant),
                'registration_status', reg.status,
                'has_open_request', EXISTS (
                    SELECT 1 FROM public.student_transfer_requests open_request
                    WHERE open_request.student_id = candidate.student_id
                      AND open_request.status IN ('submitted', 'under_review'))
            ) ORDER BY candidate.student_name, candidate.student_id), '[]'::jsonb)
            FROM (
                SELECT s.student_id,
                    COALESCE(NULLIF(btrim(u.display_name), ''),
                        NULLIF(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email) AS student_name,
                    COALESCE(s.register_number, s.student_number) AS register_number,
                    public.transfer_current_registration(s.student_id, p_tenant) AS registration_id
                FROM public.students s
                LEFT JOIN public.users u ON u.id = s.user_id
                WHERE s.institution_id = p_tenant AND s.is_active AND s.status = 'active'
                  AND s.approval_status = 'approved'
            ) candidate
            JOIN public.student_semester_registrations reg
                ON reg.semester_registration_id = candidate.registration_id
            JOIN public.academic_sections sec ON sec.academic_section_id = reg.academic_section_id
            JOIN public.admission_cohorts cohort ON cohort.admission_cohort_id = sec.admission_cohort_id
            JOIN public.programs program ON program.program_id = cohort.program_id
            JOIN public.semesters term ON term.semester_id = reg.semester_id
            WHERE term.is_active AND term.end_date >= current_date
              AND (v_departments IS NULL OR program.department_id = ANY (v_departments))
        )
    );
END;
$$;

-- One student's current section and the sections the actor may move them to.
CREATE FUNCTION public.read_direct_transfer_options(p_actor uuid, p_tenant uuid, p_student uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_role text; v_departments uuid[]; v_registration public.student_semester_registrations;
    v_current jsonb;
BEGIN
    PERFORM public.assert_transfer_backend();
    v_role := public.transfer_direct_role(p_actor, p_tenant);
    IF v_role IS NULL THEN
        RAISE EXCEPTION 'Administrator or Head of Department required' USING ERRCODE = '42501';
    END IF;
    IF v_role = 'hod' THEN
        v_departments := public.transfer_hod_departments(p_actor, p_tenant);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.students WHERE student_id = p_student AND institution_id = p_tenant
                   AND is_active AND status = 'active' AND approval_status = 'approved') THEN
        RAISE EXCEPTION 'Student not found' USING ERRCODE = 'P0002';
    END IF;
    SELECT * INTO v_registration FROM public.student_semester_registrations
    WHERE semester_registration_id = public.transfer_current_registration(p_student, p_tenant);
    IF v_registration.semester_registration_id IS NULL THEN
        RAISE EXCEPTION 'The student has no current section' USING ERRCODE = 'P1112';
    END IF;
    v_current := public.transfer_section_json(v_registration.academic_section_id, p_tenant);
    IF v_departments IS NOT NULL AND NOT (v_current->>'department_id')::uuid = ANY (v_departments) THEN
        RAISE EXCEPTION 'This student is outside your department' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object(
        'institution_id', p_tenant, 'student_id', p_student, 'actor_role', v_role,
        'current', v_current || jsonb_build_object(
            'semester_registration_id', v_registration.semester_registration_id,
            'registration_status', v_registration.status),
        'has_open_request', EXISTS (
            SELECT 1 FROM public.student_transfer_requests
            WHERE student_id = p_student AND status IN ('submitted', 'under_review')),
        'options', (
            SELECT COALESCE(jsonb_agg(option_row ORDER BY option_row->>'program_name',
                option_row->>'section_name', option_row->>'academic_section_id'), '[]'::jsonb)
            FROM (
                SELECT public.transfer_section_json(target.academic_section_id, p_tenant)
                    || jsonb_build_object(
                        'transfer_type', public.transfer_target_type(
                            v_registration.academic_section_id, target.academic_section_id, p_tenant),
                        'has_seat', public.transfer_section_has_seat(target.academic_section_id)
                    ) AS option_row
                FROM public.academic_sections target
                WHERE target.institution_id = p_tenant
                  AND target.semester_id = v_registration.semester_id
                  AND public.transfer_target_type(
                      v_registration.academic_section_id, target.academic_section_id, p_tenant) IS NOT NULL
            ) option_rows
            WHERE v_departments IS NULL OR (option_row->>'department_id')::uuid = ANY (v_departments)
        )
    );
END;
$$;

-- SOURCE direct/direct.sql sha256=80e474a0f9f454a79cc28f36bb6d4d3a90f07e609d421004367c4cede6a7680d
-- An administrator, or a Head of Department within their own department, moves
-- a student directly. No approval step: the request row is created and
-- applied in one transaction and kept as the student's placement history.
CREATE FUNCTION public.direct_transfer_student(
    p_actor uuid, p_tenant uuid, p_student uuid, p_to_section uuid, p_reason text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_role text; v_departments uuid[]; v_registration public.student_semester_registrations;
    v_kind text; v_source jsonb; v_target jsonb; v_request public.student_transfer_requests;
BEGIN
    PERFORM public.assert_transfer_backend();
    v_role := public.transfer_direct_role(p_actor, p_tenant);
    IF v_role IS NULL THEN
        RAISE EXCEPTION 'Administrator or Head of Department required' USING ERRCODE = '42501';
    END IF;
    IF v_role = 'hod' THEN
        v_departments := public.transfer_hod_departments(p_actor, p_tenant);
    END IF;
    IF length(btrim(COALESCE(p_reason, ''))) NOT BETWEEN 10 AND 2000 THEN
        RAISE EXCEPTION 'Explain the transfer in 10 to 2000 characters' USING ERRCODE = 'P1108';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-setup:' || p_tenant::text, 0));
    PERFORM 1 FROM public.students
    WHERE student_id = p_student AND institution_id = p_tenant
      AND is_active AND status = 'active' AND approval_status = 'approved'
    FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Student not found' USING ERRCODE = 'P0002';
    END IF;
    -- A student's own open request is decided first, never silently replaced.
    IF EXISTS (SELECT 1 FROM public.student_transfer_requests
               WHERE student_id = p_student AND status IN ('submitted', 'under_review')) THEN
        RAISE EXCEPTION 'The student has an open transfer request' USING ERRCODE = 'P1111';
    END IF;
    SELECT * INTO v_registration FROM public.student_semester_registrations
    WHERE semester_registration_id = public.transfer_current_registration(p_student, p_tenant)
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'The student has no current section' USING ERRCODE = 'P1112';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.semesters WHERE semester_id = v_registration.semester_id
                   AND is_active AND end_date >= current_date) THEN
        RAISE EXCEPTION 'The current term is closed' USING ERRCODE = 'P1103';
    END IF;
    v_kind := public.transfer_target_type(v_registration.academic_section_id, p_to_section, p_tenant);
    IF v_kind IS NULL THEN
        RAISE EXCEPTION 'The requested section is unavailable' USING ERRCODE = 'P1104';
    END IF;
    v_source := public.transfer_section_json(v_registration.academic_section_id, p_tenant);
    v_target := public.transfer_section_json(p_to_section, p_tenant);
    IF v_departments IS NOT NULL AND (
        NOT (v_source->>'department_id')::uuid = ANY (v_departments)
        OR NOT (v_target->>'department_id')::uuid = ANY (v_departments)) THEN
        RAISE EXCEPTION 'A Head of Department can transfer only within their department'
            USING ERRCODE = '42501';
    END IF;
    INSERT INTO public.student_transfer_requests (
        institution_id, student_id, transfer_type, semester_registration_id, semester_id,
        from_section_id, to_section_id, from_program_id, to_program_id, to_department_id,
        reason, submitted_by, initiated_by)
    VALUES (p_tenant, p_student, v_kind, v_registration.semester_registration_id,
        v_registration.semester_id, v_registration.academic_section_id, p_to_section,
        (v_source->>'program_id')::uuid, (v_target->>'program_id')::uuid,
        (v_target->>'department_id')::uuid, btrim(p_reason), p_actor, v_role)
    RETURNING * INTO v_request;
    -- Re-validates the seat and placement, records the previous registration
    -- and subjects, and marks the row approved by this actor.
    PERFORM public.transfer_apply(p_actor, p_tenant, v_request.transfer_request_id, v_role, NULL);
    INSERT INTO public.student_transfer_events
        (institution_id, transfer_request_id, actor_user_id, action, comment)
    VALUES (p_tenant, v_request.transfer_request_id, p_actor, 'transferred', btrim(p_reason));
    INSERT INTO public.admin_audit_log (actor_user_id, institution_id, action, table_name, record_id, record_data)
    VALUES (p_actor, p_tenant, 'academic.transfer.direct', 'student_transfer_requests',
        v_request.transfer_request_id::text, jsonb_build_object(
            'transferred_as', v_role, 'student_id', p_student,
            'from_section_id', v_registration.academic_section_id, 'to_section_id', p_to_section,
            'reason', btrim(p_reason)));
    RETURN jsonb_build_object('transfer_request_id', v_request.transfer_request_id,
        'institution_id', p_tenant, 'student_id', p_student, 'status', 'approved');
END;
$$;

-- SOURCE direct/security.sql sha256=826936afa14ac10aec6a49a698ca36cf62a2151a5ffe55c32074faeed7ab09c6
REVOKE ALL ON FUNCTION
    public.transfer_apply(uuid, uuid, uuid, text, text),
    public.transfer_direct_role(uuid, uuid),
    public.read_direct_transfer_students(uuid, uuid),
    public.read_direct_transfer_options(uuid, uuid, uuid),
    public.direct_transfer_student(uuid, uuid, uuid, uuid, text)
FROM PUBLIC, anon, authenticated, service_role;

GRANT EXECUTE ON FUNCTION
    public.read_direct_transfer_students(uuid, uuid),
    public.read_direct_transfer_options(uuid, uuid, uuid),
    public.direct_transfer_student(uuid, uuid, uuid, uuid, text)
TO service_role;

NOTIFY pgrst, 'reload schema';
COMMIT;
